export const COLORING_TAXONOMY:readonly ColoringCategory[]=[...top,...editorialRoots,...children.trim().split('\n').map(row=>{const [id,name,parent,visual,aliases]=row.trim().split('|'),root=top.find(x=>x.id===parent)!;return{id,name,topic:name,parent,visual,icon:subjectIcons.has(id)?id:root.icon,sample:samples[id]||'',intro:`Explore ${name.toLowerCase()} coloring pages. Choose a PDF or image to print, or add your own colors in Studio.`,aliases:aliases.split(',')} as ColoringCategory}),...editorialTopics,...NOVEMBER_27_TOPICS,...NOVEMBER_06_TOPICS,...NOVEMBER_07_CAR_BRAND_TOPICS,...NOVEMBER_07_ADDITIONAL_CAR_BRAND_TOPICS,...NOVEMBER_08_AUTOMOBILE_BRAND_TOPICS,...NOVEMBER_09_AUTO29_TOPICS,...NOVEMBER_07_FIVE_TOPICS,...NOVEMBER_07_ADDITIONAL_TOPICS,...SCOOBY_DOO_TOPICS,...letterTopics];
const reviewedCatalogIntros:Record<string,string>={"animals":"Meet lions, elephants, woodland animals, pandas, koalas, and other wildlife in simple poses and detailed habitats. Pet, farm, ocean, and polar themes offer more ways to explore the collection.","flowers":"Explore roses, tulips, daisies, sunflowers, orchids, and other blossoms, from single stems to bouquets and elaborate gardens. Petal shapes, leaves, patterned pots, and glasshouse details give each page a different focus.","mandalas":"Petals, leaves, stars, paisley curls, butterflies, and fish form repeating circular designs. Choose broad shapes with open centers or tightly layered patterns with fine details.","dinosaurs":"Horned dinosaurs, plated backs, long necks, feathered forms, and hatchlings appear among ferns, rivers, and rocky landscapes. The drawings range from single animals to detailed forest and nesting scenes.","cats":"Kittens and cats stretch, sleep, play with yarn, and explore windows, gardens, and climbing towers. Find smooth coats, fluffy fur, outlined patches, and varied rooms and outdoor settings.","dogs":"Dogs and puppies appear in open portraits, playful toy scenes, gardens, ponds, home interiors, and moments with children or caregivers. Long ears, curly coats, short legs, shaggy fur, and distinctive poses give the collection varied silhouettes. Choose an individual pet or a fuller outdoor or household setting, then open its page to print or color online.","cars":"Hatchbacks, sedans, sports cars, pickups, and camper-style vehicles appear on open roads and in detailed streets and garages. Imaginative vehicle concepts are identified as concepts in their individual titles.","unicorns":"Single-horned unicorns explore flower gardens, woodland paths, clouds, and imagined castles. Choose a clear character outline or a scene with patterned manes, plants, and architectural details.","spring":"New leaves, blossoms, rain puddles, nesting birds, and young animals fill these spring scenes. Garden activities, flower markets, streams, and glasshouses bring more detail to the collection.","halloween":"Pumpkins, friendly ghosts, bats, black cats, costumes, and decorated houses create playful Halloween scenes. Open character outlines sit alongside detailed lantern-lit gardens and imaginative interiors.","easter":"Decorated eggs, rabbits, chicks, baskets, and spring flowers form the Easter collection. Simple arrangements and detailed gardens offer different amounts of pattern and background to color.","valentines-day":"Hearts, roses, paired animals, gift boxes, letters, and tea sets fill these Valentine designs. Choose a simple motif or an ornate floral frame with fine decorative details.","thanksgiving":"Turkeys, pumpkins, harvest baskets, autumn leaves, and shared meal scenes make up this Thanksgiving collection. Clear single subjects and detailed kitchens, porches, and harvest arrangements offer a range of drawing detail.","roses":"Single roses, buds, tied bunches, garden arches, and formal fountain gardens highlight layered petals and serrated leaves.","sunflowers":"Large sunflower heads, broad leaves, tied bouquets, cottage entrances, and covered garden seats offer bold flower shapes and varied backgrounds.","bouquets":"Tied stems, wrapped flowers, patterned vases, and flower-arranging tables bring together blossoms of different shapes and sizes.","garden-flowers":"Tulips, daisies, lilies, orchids, and other garden blossoms appear in pots, flower beds, woodland patches, and conservatories.","floral-mandalas":"Layered petals, leaves, tulip shapes, and botanical curls repeat around a central flower in broad or finely patterned rings.","geometric-mandalas":"Stars, diamonds, angular petals, lattice bands, and celestial motifs form circular patterns with clearly repeated sections.","animal-mandalas":"Butterflies, fish, feather-eye motifs, shells, and starfish repeat among flowers and flowing shapes in circular ornamental designs.","fantasy":"Unicorns, dragons, and storybook princesses explore gardens, castles, woodland paths, and imagined floating worlds. Simple character outlines and detailed scenes offer different ways to invent a palette.","holidays":"Pumpkins and friendly ghosts, Easter eggs and rabbits, harvest turkeys, Valentine hearts, and winter decorations mark different celebrations. Browse a holiday theme for simple motifs and detailed seasonal scenes.","vehicles":"Cars, camper vans, bicycles, boats, and other vehicles appear in roads, workshops, gardens, and imagined adventures. Explore each vehicle theme for clear outlines and scenes with more background detail.","sharks":"Hammerheads, spotted whale sharks, long-tailed threshers, and other sharks explore reefs, kelp forests, and mangrove channels. Simple profiles and richly detailed underwater scenes show different silhouettes and fin shapes.","sea-turtles":"Sea turtles hatch on sandy shores and glide among coral, kelp, mangrove roots, and reef fish. Explore expressive hatchlings, patterned flippers, and detailed underwater habitats.","birthdays":"Happy Birthday lettering tops cakes, gifts, playful animals, family celebrations, and imagined party settings. Open outlines and elaborate tea tables, gardens, bakeries, and fantasy scenes offer varied coloring detail."};
reviewedCatalogIntros.education='Explore alphabet letters, individual letter collections, numbers and counting, shapes, and classroom subjects. Each letter and number has its own topic page, while the wider collection brings the learning themes together.';
reviewedCatalogIntros.alphabet='Explore uppercase and lowercase forms from A to Z, decorative letter studies, and pictured examples that connect letters with words. Open a letter collection to find its individual coloring pages and matching PDF or WebP files.';
for(const category of COLORING_TAXONOMY){const intro=reviewedCatalogIntros[category.id];if(intro)category.intro=intro;}
export const ROOT_CATEGORIES=COLORING_TAXONOMY.filter(c=>!c.parent);
export const VISION_ROOT_CATEGORIES=ROOT_CATEGORIES.filter(c=>!c.editorial_only);
const byId=new Map(COLORING_TAXONOMY.map(c=>[c.id,c]));
export function categoryById(id:string){return byId.get(id);}
export function childCategories(id:string){return COLORING_TAXONOMY.filter(c=>c.parent===id);}
export function visionChildCategories(id:string){return childCategories(id).filter(c=>!c.editorial_only);}
export function categoryPath(id:string){const c=byId.get(id);return c?publicCategoryPath(c.id,c.parent):'/coloring-pages/';}
export function categoryLineage(id:string):string[]{const path:string[]=[];let current=byId.get(id);while(current){path.unshift(current.id);current=current.parent?byId.get(current.parent):undefined;}return path;}
// Reject ambiguous aliases rather than silently mapping one word to two collections.
const aliases=new Map<string,Set<string>>();
for(const c of COLORING_TAXONOMY)for(const raw of [c.id,c.name,...c.aliases]){const key=raw.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();if(!aliases.has(key))aliases.set(key,new Set());aliases.get(key)!.add(c.id);}
export function resolveCategoryAlias(value:string){const direct=value.toLowerCase().trim();if(byId.has(direct))return direct;const values=aliases.get(value.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim());return values?.size===1?[...values][0]:undefined;}
